package com.splitmate.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="expenses") public class Expense { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="household_id",nullable=false) public Long householdId; @Column(name="paid_by",nullable=false) public Long paidBy; @Column(nullable=false,length=180) public String description; @Column(nullable=false,length=40) public String category; @Column(nullable=false,precision=12,scale=2) public BigDecimal amount; @Column(name="expense_date",nullable=false) public LocalDate expenseDate; @Column(name="split_type",nullable=false,length=20) public String splitType; @Column(name="created_at",nullable=false) public Instant createdAt=Instant.now(); protected Expense(){} public Expense(Long h,Long u,String d,String c,BigDecimal a,LocalDate date,String split){householdId=h;paidBy=u;description=d;category=c;amount=a;expenseDate=date;splitType=split;} }
